try:
    initial_balance = float(input().strip())
    if initial_balance < 0:
        raise ValueError("Invalid initial balance")
    balance = initial_balance
except ValueError as e:
    if str(e) == "Invalid initial balance":
        print("Invalid initial balance")
    else:
        print("Invalid initial balance")
    exit()

try:
    withdraw_amount = float(input().strip())
    if withdraw_amount <= 0:
        raise ValueError("Invalid withdrawal amount")
    if withdraw_amount > balance:
        raise ValueError("Insufficient balance")
    balance -= withdraw_amount
    print("Withdrawal successful")
    print(f"Remaining balance: {int(balance) if balance == int(balance) else balance}")
except ValueError as e:
    print(str(e))
